#!/usr/bin/env bash
# СУДИТ: hooks/completion-gate.sh
# probe_D1132 — «Проверка» закрытого пункта, не уложившаяся в срок одной команды (CG_TIMEOUT), — «не проверена», а не
# «закрытие расходится со своим критерием». Красная (1), пока исключение по сроку засчитывается кодом 125 как красное
# закрытие (26 октября 2026: зелёная «Проверка» D1120 идёт 96 с при сроке 60 — гейт объявил её расходящейся).
# Положительный контроль — быстрая красная «Проверка» закрытого пункта названа расходящейся. Рамка — 2.
. "$(dirname "$0")/../alerts-read.sh"
R="${CLAUDSOUL_REPO:-$(cd "$(dirname "$0")/../../.." && pwd)}"
HOOK="$R/hooks/completion-gate.sh"; [ -f "$HOOK" ] && command -v jq >/dev/null 2>&1 || exit 2
T=$(mktemp -d "${TMPDIR:-/tmp}/probe-D1132.XXXXXX") || exit 2
mkdir -p "$T/state"; BL="$T/BACKLOG.md"
printf '%s\n' '# BACKLOG' '' \
    '- ☑ **D2000** закрытый, проверка медленная' '  **Корень.** R6 — два состояния.' '  **Результат.** x.' '  **Проверка.** `sleep 4; exit 0` → 0' '  **Показание.** «Проверка» 0.' '' \
    '- ☑ **D2001** закрытый, проверка красная' '  **Корень.** R6 — два состояния.' '  **Результат.** x.' '  **Проверка.** `exit 1` → 0' '  **Показание.** «Проверка» 0.' > "$BL"
printf '{"session_id":"p1132","cwd":"%s"}' "$T" | env -u BACKLOG_CHECKS_NESTED CG_TIMEOUT=1 CG_BACKLOG="$BL" CG_LOCAL_BACKLOG="" \
    STATE_DIR="$T/state" bash "$HOOK" >/dev/null 2>&1
out=$(alerts_of "$T/state")
red=$(printf '%s\n' "$out" | awk '/расходится со своим/ { on = 1; next } on && /^D[0-9]+ \(rc=/ { print $1 } on && !/^D[0-9]+ \(rc=/ { on = 0 }')
grep -qx 'D2001' <<< "$red" || exit 2
grep -qx 'D2000' <<< "$red" && { echo "закрытие с «Проверкой» дольше срока названо расходящимся" >&2; exit 1; }
grep -q 'не проверена.*D2000' <<< "$out" || { echo "«Проверка» дольше срока не названа непроверенной" >&2; exit 1; }
echo "не уложилась в срок — «не проверена», а не красная"
exit 0
